import {traits,band} from './model.mjs';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function thinkingViews(language='en'){return language==='hi'?[{key:'map',title:'आपकी अंदरूनी तस्वीर',prompt:'आपकी पसंद की पूरी झलक',icon:'✧'},{key:'bar',title:'आपकी सहज पसंद',prompt:'आपको क्या ज़्यादा सहज लगता है?',icon:'↔'},{key:'pie',title:'आपकी पसंद का मेल',prompt:'दो पसंद एक साथ कैसे दिखती हैं?',icon:'⤨'},{key:'line',title:'समय के साथ आपकी यात्रा',prompt:'आपकी अपनी बदलती झलक',icon:'⌁'}]:[{key:'map',title:'Your inner landscape',prompt:'See your whole pattern',icon:'✧'},{key:'bar',title:'Your natural preferences',prompt:'Find what feels natural',icon:'↔'},{key:'pie',title:'How your traits meet',prompt:'Explore two sides of you together',icon:'⤨'},{key:'line',title:'Your journey over time',prompt:'Revisit your own snapshots',icon:'⌁'}]}
export function normalizePair(pair){const first=Number.isInteger(pair?.[0])&&pair[0]>=0&&pair[0]<5?pair[0]:0;const second=Number.isInteger(pair?.[1])&&pair[1]>=0&&pair[1]<5&&pair[1]!==first?pair[1]:(first+1)%5;return[first,second]}
export function connectionPoint(scores,pair){if(!Array.isArray(scores)||scores.length!==5||Array.from(scores).some(s=>!Number.isFinite(s)||s<0||s>100))throw new Error('Invalid scores.');const [a,b]=normalizePair(pair);return{a,b,xScore:scores[a],yScore:scores[b],x:65+scores[a]*2.7,y:310-scores[b]*2.7}}
export function preferencePathsMarkup(report,index,language='en'){const hi=language==='hi';return `<div class="thinking-view preference-paths" data-no-translate><p class="view-question">${hi?'हर पसंद की अपनी जगह है। आपकी पसंद कहाँ बैठती है?':'Every preference has a place. Where do yours feel at home?'}</p><p class="view-intro">${hi?'हर रास्ते के दोनों सिरे पढ़ें। किसी एक को चुनकर उसकी कहानी और एक छोटा कदम देखें।':'Read both ends of each path. Choose one to explore its story and a small step you can try.'}</p><div class="preference-path-list">${traits.map((trait,i)=>`<button class="preference-path" data-category="${i}" aria-pressed="${i===index}" style="--path-color:${trait.color};--path-position:${report.scores[i]}%"><span class="path-heading"><strong>${esc(trait.name)}</strong><span>${report.scores[i]} <small>/ 100</small></span></span><span class="path-rail" aria-hidden="true"><span class="path-middle"></span><span class="path-dot"></span></span><span class="path-endpoints"><span>${esc(trait.low)}</span><span>${esc(trait.high)}</span></span><span class="path-meaning">${esc(trait.profiles[band(report.scores[i])].title)} <span aria-hidden="true">→</span></span></button>`).join('')}</div></div>`}
export function connectionsMarkup(report,pair,language='en',selected=0){const hi=language==='hi',point=connectionPoint(report.scores,pair),a=traits[point.a],b=traits[point.b];return `<div class="thinking-view connections-view" data-no-translate><p class="view-question">${hi?'आपकी दो पसंद, एक ही तस्वीर में।':'Two preferences. One picture of you.'}</p><p class="view-intro">${hi?'दो आयाम चुनें और देखें कि आपके scores साथ कहाँ बैठते हैं। यह उनका मेल दिखाता है, व्यवहार की भविष्यवाणी नहीं।':'Choose two dimensions and see where your scores meet. This brings two preferences together; it does not predict your behavior.'}</p><div class="connection-controls">${[point.a,point.b].map((chosen,axis)=>`<label>${hi?(axis===0?'बाएँ से दाएँ':'नीचे से ऊपर'):(axis===0?'Across the picture':'Up the picture')}<select data-connection-axis="${axis}">${traits.map((trait,i)=>`<option value="${i}" ${i===chosen?'selected':''}>${esc(trait.name)}</option>`).join('')}</select></label>`).join('')}</div><div class="connection-picture"><p class="connection-y-note"><span aria-hidden="true">↑</span> ${esc(b.high)}</p><svg viewBox="0 0 400 360" role="group" aria-label="${esc(a.name)} ${point.xScore} / 100; ${esc(b.name)} ${point.yScore} / 100"><defs><linearGradient id="connection-wash"><stop stop-color="#edf2fc"/><stop offset="1" stop-color="#faf6ee"/></linearGradient></defs><rect x="65" y="40" width="270" height="270" rx="14" fill="url(#connection-wash)"/>${[0,25,50,75,100].map(n=>`<path d="M${65+n*2.7} 40v270M65 ${310-n*2.7}h270" stroke="${n===50?'#aab9d5':'#dde5f1'}" stroke-dasharray="${n===50?'5 5':'0'}"/>`).join('')}<path d="M65 ${point.y}H${point.x}V310" fill="none" stroke="#7d94c5" stroke-dasharray="4 4"/>${[0,50,100].map(n=>`<text x="${65+n*2.7}" y="337" text-anchor="middle" font-size="14" fill="#627087">${n}</text><text x="49" y="${315-n*2.7}" text-anchor="end" font-size="14" fill="#627087">${n}</text>`).join('')}<a href="#category-details" data-category="${point.a}" aria-label="${hi?'इस पसंद की कहानी पढ़ें':'Read this preference’s story'}: ${esc(a.name)}"><circle cx="${point.x}" cy="${point.y}" r="23" fill="#526cb51c"/><circle cx="${point.x}" cy="${point.y}" r="10" fill="#526cb5" stroke="white" stroke-width="3"/><title>${esc(a.name)} ${point.xScore}; ${esc(b.name)} ${point.yScore}</title></a></svg><div class="connection-x-notes"><span>← ${esc(a.low)}</span><span>${esc(a.high)} →</span></div><p class="connection-bottom-note">${hi?'नीचे':'Lower end'}: ${esc(b.low)}</p></div><div class="connection-traits">${[point.a,point.b].map(i=>`<button data-category="${i}" aria-pressed="${i===selected}" style="--connection-color:${traits[i].color}"><span>${esc(traits[i].name)} · ${report.scores[i]} / 100</span><strong>${esc(traits[i].profiles[band(report.scores[i])].title)}</strong><small>${hi?'इस हिस्से को समझें →':'Explore this side of you →'}</small></button>`).join('')}</div><p class="connection-takeaway">${hi?'ये दोनों बातें आपके बारे में एक साथ सही हो सकती हैं। अलग परिस्थिति में अलग पसंद आगे आ सकती है।':'Both can be true about you. A different setting may bring a different preference to the foreground.'}</p></div>`}
export function connectionReading(report,pair,language='en'){const hi=language==='hi',p=connectionPoint(report.scores,pair);return `<div class="graph-reading" data-no-translate><strong>${hi?'इन दो पसंदों का साथ देखें':'Notice how these two preferences coexist'}</strong><p>${esc(traits[p.a].name)}: ${p.xScore} / 100 · ${esc(traits[p.b].name)}: ${p.yScore} / 100. ${hi?'दोनों को जगह देने वाली परिस्थिति कैसी होगी? किसी एक की कहानी पढ़कर शुरुआत करें।':'What kind of situation could make room for both? Start by exploring either preference’s story.'}</p></div>`}
export function journeyMarkup(report,series,index,language='en',formatDate=date=>new Date(date).toLocaleDateString(language)){if(!Array.isArray(series)||!series.length)return `<p>${language==='hi'?'अपनी पहली झलक के लिए assessment पूरा करें।':'Complete an assessment to begin your own journey.'}</p>`;const hi=language==='hi',trait=traits[index],first=series[0],last=series.at(-1),left=50,right=550,top=35,bottom=220,x=i=>series.length===1?300:left+i*(right-left)/(series.length-1),y=score=>bottom-score/100*(bottom-top);return `<div class="thinking-view journey-view" data-no-translate><p class="view-question">${hi?'क्या पहले जैसा लगता है, और क्या अलग?':'What feels familiar, and what feels different?'}</p><div class="history-category-control"><label for="history-category">${hi?'अपनी यात्रा का एक पहलू चुनें':'Choose one side of your journey'}</label><select id="history-category">${traits.map((t,i)=>`<option value="${i}" ${i===index?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><p class="view-intro">${series.length===1?(hi?'यह आपकी पहली saved झलक है। जब चाहें एक और reflection पूरा करें; वह इस यात्रा का अगला पड़ाव होगा।':'This is your first saved snapshot. Another reflection, whenever you feel ready, becomes the next stop on your journey.'):(hi?`${formatDate(first.date)} से ${formatDate(last.date)} तक, इस पहलू में आपके जवाब ${first.score} से ${last.score} हुए। परिस्थिति और ऊर्जा बदल सकती हैं; हर बदलाव सुधार या गिरावट नहीं है।`:`From ${formatDate(first.date)} to ${formatDate(last.date)}, your responses on this dimension moved from ${first.score} to ${last.score}. Context and energy can change; a difference is not automatically improvement or decline.`)}</p><svg class="history-line journey-trail-picture" viewBox="0 0 600 265" role="group" aria-label="${esc(trait.name)} · ${series.length} ${hi?'saved झलक':'saved snapshots'}">${[0,50,100].map(n=>`<path d="M${left} ${y(n)}H${right}" stroke="#dce4f1" stroke-dasharray="${n===50?'5 5':'0'}"/><text x="38" y="${y(n)+5}" text-anchor="end" font-size="14" fill="#627087">${n}</text>`).join('')}${series.length>1?`<polyline points="${series.map((point,i)=>`${x(i)},${y(point.score)}`).join(' ')}" fill="none" stroke="${trait.color}" stroke-width="3"/>`:''}${series.map((point,i)=>`<a href="#history-point-detail" data-history-point="${i}" aria-label="${esc(formatDate(point.date))}: ${point.score} / 100"><circle cx="${x(i)}" cy="${y(point.score)}" r="20" fill="transparent"/><circle cx="${x(i)}" cy="${y(point.score)}" r="7" fill="${trait.color}" stroke="#fff" stroke-width="3"/><title>${esc(formatDate(point.date))}: ${point.score}</title></a><text x="${x(i)}" y="250" text-anchor="middle" font-size="14" fill="#627087">${i+1}</text>`).join('')}</svg><p id="history-point-detail" class="history-point-detail" role="status">${esc(formatDate(last.date))} · ${esc(trait.name)}: <strong>${last.score} / 100</strong></p><div class="journey-snapshots">${series.map((point,i)=>`<button data-history-point="${i}" class="journey-snapshot ${i===series.length-1?'active':''}"><span>${hi?'पड़ाव':'Snapshot'} ${i+1}</span><strong>${point.score}<small> / 100</small></strong><span>${esc(formatDate(point.date))}</span><p>${esc(trait.profiles[band(point.score)].title)}</p></button>`).join('')}</div></div>`}
